{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Isradipine, a lipophilic dihydropyridine, has a systemic availability of 17% in healthy volunteers after oral administration, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pentazocine, a lipophilic drug with extensive first-pass metabolism, has an oral bioavailability of 0.18 in normal subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib, a poorly soluble drug, has a mean absolute oral bioavailability of 13.9% in the fed state, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Nifedipine, a smaller lipophilic dihydropyridine, has an oral bioavailability of 45 ± 8% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic polyprenyl benzoquinone (ubiquinone) with a large nonpolar side chain and no ionizable groups. Although some lipophilic drugs in the evidence exceed 20% F, the extreme lipophilicity, high molecular weight, and known poor oral absorption behavior of ubiquinones support F < 20%; therefore predicted low.",
  "evidence_gaps": [
    "No direct oral bioavailability data for ubiquinone/coenzyme Q analogs are present in the provided records.",
    "Structural similarity between the query and the evidence molecules is low, so transferability is limited.",
    "No formulation, food-effect, or dose information is available for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

